select updated_at
  from batch.tenant_configuration_revision
 where tenant_id = #{tenantId}

select exists (
    select 1
      from batch.scheduled_occurrence_coverage coverage
      left join batch.tenant_configuration_revision revision
        on revision.tenant_id = coverage.tenant_id
     where coverage.tenant_id = #{tenantId}
       and coverage.workflow_definition_id = #{workflowDefinitionId}
       and coverage.configuration_revision = coalesce(revision.revision, 0)
)

