insert into batch.scheduled_occurrence (
    tenant_id, workflow_definition_id, workflow_code, schedule_version, calendar_code,
    scheduled_fire_time, biz_date, occurrence_status
) values (
    #{tenantId}, #{workflowDefinitionId}, #{workflowCode}, #{scheduleVersion}, #{calendarCode},
    #{scheduledFireTime}, #{bizDate}, #{targetStatus}
)

mapper.update:
update batch.scheduled_occurrence
set occurrence_status = #{newStatus},
    request_id = coalesce(#{requestId}, request_id),
    misfire_detected_at = case when #{newStatus} = 'MISFIRE_PENDING'
        then coalesce(misfire_detected_at, CURRENT_TIMESTAMP) else misfire_detected_at end,
    updated_at = CURRENT_TIMESTAMP
where tenant_id = #{tenantId}
  and workflow_definition_id = #{workflowDefinitionId}
  and scheduled_fire_time = #{scheduledFireTime}
  and occurrence_status = #{expectedStatus}
  and (#{newStatus} != 'MISFIRE_PENDING' or exists (
      select 1 from batch.workflow_definition wf
      where wf.tenant_id = #{tenantId} and wf.id = #{workflowDefinitionId} and wf.enabled = true
  ))

update batch.scheduled_occurrence
set occurrence_status = #{targetStatus},
    request_id = #{requestId},
    updated_at = CURRENT_TIMESTAMP
where tenant_id = #{tenantId}
  and workflow_definition_id = #{workflowDefinitionId}
  and scheduled_fire_time = #{scheduledFireTime}
  and biz_date = #{bizDate}
  and occurrence_status = 'CLOSED_DAY_REJECTED'
  and request_id is null

