select scheduled_fire_time
  from batch.scheduled_occurrence
 where tenant_id = #{tenantId}
   and workflow_definition_id = #{workflowDefinitionId}
   and schedule_version = #{scheduleVersion}
   and occurrence_status = 'PLANNED'
   and request_id is null
   and scheduled_fire_time < #{beforeExclusive}
 order by scheduled_fire_time
 limit #{limit}

