   set occurrence_status = #{nextStatus}, updated_at = CURRENT_TIMESTAMP
 where tenant_id = #{wait.tenantId}
   and workflow_definition_id = #{wait.workflowDefinitionId}
   and scheduled_fire_time = #{wait.scheduledFireTime}
   and occurrence_status = 'WAITING_READINESS'
   and readiness_deadline <= #{now}

