set occurrence_status = #{targetStatus},
    updated_at = CURRENT_TIMESTAMP
where tenant_id = #{tenantId}
  and workflow_code = #{workflowCode}
  and scheduled_fire_time > #{now}
  and occurrence_status = 'PLANNED'

mapper.select:
select coverage_from_at, coverage_through_at
  from batch.scheduled_occurrence_coverage
 where tenant_id = #{tenantId}
   and workflow_definition_id = #{workflowDefinitionId}
   and schedule_version = #{scheduleVersion}
   and calendar_code is not distinct from #{calendarCode}

select count(*)
from batch.scheduled_occurrence
where tenant_id = #{tenantId}
  and calendar_code = #{calendarCode}
  and biz_date = #{bizDate}
  and (
      occurrence_status in (
          'PLANNED', 'WAITING_READINESS', 'MISFIRE_PENDING'
      )
      or (
          occurrence_status = 'REQUESTED'
          and not exists (
              select 1
              from batch.trigger_request tr
              join batch.job_instance ji
                on ji.tenant_id = tr.tenant_id
               and ji.trigger_request_id = tr.id
              where tr.tenant_id = batch.scheduled_occurrence.tenant_id
                and tr.request_id = batch.scheduled_occurrence.request_id
          )
      )
  )

